def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    out=[r[:] for r in grid]
    diamonds=[]
    for r in range(h):
        for c in range(w):
            for d in range(1,min(r,c,h-1-r,w-1-c)+1):
                col=grid[r-d][c]
                if not col: continue
                edge=set()
                for dy in range(-d,d+1):
                    dx=d-abs(dy)
                    edge.add((r+dy,c+dx));edge.add((r+dy,c-dx))
                if not all(grid[y][x]==col for y,x in edge): continue
                inside=[(y,x) for y in range(r-d+1,r+d) for x in range(c-d+1,c+d) if abs(y-r)+abs(x-c)<d]
                seeds=[(y,x) for y,x in inside if grid[y][x]!=0 and grid[y][x]!=col]
                if seeds: diamonds.append((d,inside,seeds))
    for d,inside,seeds in sorted(diamonds,reverse=True):
        kinds=Counter((grid[y][x],(y+x)%2) for y,x in seeds)
        color,parity=kinds.most_common(1)[0][0]
        for y,x in inside:
            if grid[y][x]==0 and (y+x)%2==parity: out[y][x]=color
    return out

